maintenance_records	CREATE TABLE `maintenance_records` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `vehicleId` int(11) NOT NULL,\n  `technicianId` int(11) NOT NULL,\n  `currentHours` double NOT NULL,\n  `hoursToNextService` double NOT NULL DEFAULT 250,\n  `alertTier` enum('GREEN','AMBER','RED') NOT NULL DEFAULT 'GREEN',\n  `checklistJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`checklistJson`)),\n  `status` enum('SCHEDULED','IN_SERVICE','COMPLETED') NOT NULL DEFAULT 'SCHEDULED',\n  `completedAt` datetime(3) DEFAULT NULL,\n  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),\n  `updatedAt` datetime(3) NOT NULL,\n  PRIMARY KEY (`id`),\n  KEY `maintenance_records_vehicleId_idx` (`vehicleId`),\n  KEY `maintenance_records_technicianId_idx` (`technicianId`),\n  KEY `maintenance_records_status_idx` (`status`),\n  CONSTRAINT `maintenance_records_technicianId_fkey` FOREIGN KEY (`technicianId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `maintenance_records_vehicleId_fkey` FOREIGN KEY (`vehicleId`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci


-- ================= TABLE: repair_tickets ================
Table	Create Table
repair_tickets	CREATE TABLE `repair_tickets` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `code` varchar(191) NOT NULL,\n  `vehicleId` int(11) NOT NULL,\n  `reportedByDriverId` int(11) DEFAULT NULL,\n  `assignedTechnicianId` int(11) DEFAULT NULL,\n  `repairTier` enum('TIEU_TU','TRUNG_TU','DAI_TU','SOS_CUU_HO') NOT NULL DEFAULT 'TIEU_TU',\n  `issueDescription` text NOT NULL,\n  `isGeneratedFromMaintenance` tinyint(1) NOT NULL DEFAULT 0,\n  `maintenanceRecordId` int(11) DEFAULT NULL,\n  `status` enum('RECEIVED','IN_REPAIR','WAITING_PARTS','COMPLETED') NOT NULL DEFAULT 'RECEIVED',\n  `estimatedCostVnd` double NOT NULL DEFAULT 0,\n  `actualCostVnd` double NOT NULL DEFAULT 0,\n  `replacedPartsJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`replacedPartsJson`)),\n  `receivedDate` datetime(3) NOT NULL DEFAULT current_timestamp(3),\n  `completedDate` datetime(3) DEFAULT NULL,\n  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),\n  `updatedAt` datetime(3) NOT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `repair_tickets_code_key` (`code`),\n  KEY `repair_tickets_vehicleId_idx` (`vehicleId`),\n  KEY `repair_tickets_repairTier_idx` (`repairTier`),\n  KEY `repair_tickets_status_idx` (`status`),\n  KEY `repair_tickets_reportedByDriverId_fkey` (`reportedByDriverId`),\n  KEY `repair_tickets_assignedTechnicianId_fkey` (`assignedTechnicianId`),\n  KEY `repair_tickets_maintenanceRecordId_fkey` (`maintenanceRecordId`),\n  CONSTRAINT `repair_tickets_assignedTechnicianId_fkey` FOREIGN KEY (`assignedTechnicianId`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,\n  CONSTRAINT `repair_tickets_maintenanceRecordId_fkey` FOREIGN KEY (`maintenanceRecordId`) REFERENCES `maintenance_records` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,\n  CONSTRAINT `repair_tickets_reportedByDriverId_fkey` FOREIGN KEY (`reportedByDriverId`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,\n  CONSTRAINT `repair_tickets_vehicleId_fkey` FOREIGN KEY (`vehicleId`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci


