workshop_owed_part_notes	CREATE TABLE `workshop_owed_part_notes` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `maintenanceRecordId` int(11) NOT NULL,\n  `vehicleId` int(11) NOT NULL,\n  `missingPartName` varchar(191) NOT NULL,\n  `partCode` varchar(191) DEFAULT NULL,\n  `scheduledRestockDate` datetime(3) DEFAULT NULL,\n  `isResolved` tinyint(1) NOT NULL DEFAULT 0,\n  `resolvedAt` datetime(3) DEFAULT NULL,\n  `technicianNotes` text DEFAULT NULL,\n  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),\n  `updatedAt` datetime(3) NOT NULL,\n  PRIMARY KEY (`id`),\n  KEY `workshop_owed_part_notes_maintenanceRecordId_idx` (`maintenanceRecordId`),\n  KEY `workshop_owed_part_notes_vehicleId_idx` (`vehicleId`),\n  KEY `workshop_owed_part_notes_isResolved_idx` (`isResolved`),\n  CONSTRAINT `workshop_owed_part_notes_maintenanceRecordId_fkey` FOREIGN KEY (`maintenanceRecordId`) REFERENCES `maintenance_records` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `workshop_owed_part_notes_vehicleId_fkey` FOREIGN KEY (`vehicleId`) REFERENCES `vehicles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci


-- ================= TABLE: driver_kpis ================
Table	Create Table
driver_kpis	CREATE TABLE `driver_kpis` (\n  `id` int(11) NOT NULL AUTO_INCREMENT,\n  `driverId` int(11) NOT NULL,\n  `monthYear` varchar(191) NOT NULL,\n  `tripsCount` int(11) NOT NULL DEFAULT 0,\n  `tripsScore` double NOT NULL DEFAULT 25,\n  `distanceKm` double NOT NULL DEFAULT 0,\n  `distanceScore` double NOT NULL DEFAULT 25,\n  `machineHours` double NOT NULL DEFAULT 0,\n  `hoursScore` double NOT NULL DEFAULT 25,\n  `fuelSavedLiters` double NOT NULL DEFAULT 0,\n  `fuelScore` double NOT NULL DEFAULT 25,\n  `totalScore` double NOT NULL DEFAULT 100,\n  `rankGrade` enum('HANG_A','HANG_B','HANG_C','HANG_D') NOT NULL DEFAULT 'HANG_A',\n  `bonusAmountVnd` double NOT NULL DEFAULT 1500000,\n  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),\n  `updatedAt` datetime(3) NOT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `driver_kpis_driverId_monthYear_key` (`driverId`,`monthYear`),\n  KEY `driver_kpis_driverId_idx` (`driverId`),\n  KEY `driver_kpis_rankGrade_idx` (`rankGrade`),\n  CONSTRAINT `driver_kpis_driverId_fkey` FOREIGN KEY (`driverId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci


-- ================= TABLE: driver_sos_alerts ================
