-- ================= TABLE: catalogs ================
Table	Create Table
catalogs	CREATE TABLE `catalogs` (\n  `id` varchar(191) NOT NULL,\n  `code` varchar(191) NOT NULL,\n  `name` varchar(191) NOT NULL,\n  `type` enum('COMPLEX','DEPARTMENT','ENTERPRISE','FARM','TEAM','PLOT','LAND_PARCEL') NOT NULL,\n  `parentCode` varchar(191) DEFAULT NULL,\n  `parentName` varchar(191) DEFAULT NULL,\n  `enterpriseName` varchar(191) DEFAULT NULL,\n  `farmName` varchar(191) DEFAULT NULL,\n  `plotStatus` varchar(191) DEFAULT NULL,\n  `systemId` varchar(191) DEFAULT NULL,\n  `address` varchar(191) DEFAULT NULL,\n  `managerName` varchar(191) DEFAULT NULL,\n  `phone` varchar(191) DEFAULT NULL,\n  `areaHa` double DEFAULT NULL,\n  `status` varchar(191) NOT NULL DEFAULT 'HOAT_DONG',\n  `description` text DEFAULT NULL,\n  `createdUser` varchar(191) DEFAULT 'admin',\n  `createdDate` varchar(191) DEFAULT NULL,\n  `updatedUser` varchar(191) DEFAULT 'admin',\n  `updatedDate` varchar(191) DEFAULT NULL,\n  `confirmedUser` varchar(191) DEFAULT NULL,\n  `confirmedDate` varchar(191) DEFAULT NULL,\n  `deletedUser` varchar(191) DEFAULT NULL,\n  `deletedDate` varchar(191) DEFAULT NULL,\n  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),\n  `updatedAt` datetime(3) NOT NULL,\n  PRIMARY KEY (`id`),\n  KEY `catalogs_type_idx` (`type`),\n  KEY `catalogs_code_idx` (`code`),\n  KEY `catalogs_parentCode_idx` (`parentCode`),\n  KEY `catalogs_status_idx` (`status`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci


